using System;using System.IO;
public static class PaletteTargets88 {
 public static void Main(string[] args){using(var r=new BinaryReader(File.OpenRead(args[0])))using(var w=new BinaryWriter(File.Create(args[1]))){int n=r.ReadInt32(),levels=r.ReadInt32();if(n<1||n>16384||levels<2||levels>256)throw new ArgumentException("88 palette ABI");var p=new SourcePalette58.Settings{count=levels,darkLRatio=r.ReadDouble(),darkCRatio=r.ReadDouble(),gamma=r.ReadDouble(),intervalScale=r.ReadDouble()};w.Write(n);w.Write(levels);for(int i=0;i<n;i++){var rgb=new[]{r.ReadInt32(),r.ReadInt32(),r.ReadInt32()};var palette=SourcePalette58.MakePalette(new SourcePalette58.Reference{rgb8=rgb},p);var lab=SourcePalette58.LabRGB(rgb);double hue=Math.Atan2(lab[2],lab[1]);for(int k=0;k<levels;k++){var target=SourcePalette58.LinearLch(palette.targetL[k],palette.usedC[k],hue);for(int j=0;j<3;j++)w.Write(k==levels-1||p.intervalScale==0?rgb[j]:Math.Max(0,Math.Min(255,255*SourcePalette58.Encode(target[j]))));foreach(int v in palette.rgb8[k])w.Write((byte)v);}}if(r.BaseStream.Position!=r.BaseStream.Length)throw new ArgumentException("88 trailing input");}}
}
